SELECT * FROM image_generation_execution
WHERE execution_source = #{executionSource} AND session_id = #{sessionId}
ORDER BY started_at DESC, image_generation_execution_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM image_generation_execution_input_artifact
WHERE image_generation_execution_id = #{imageGenerationExecutionId}
ORDER BY input_role ASC, input_order ASC
